-- ========================================================


local interval = 0.8    -- 若两次 SetTargetPos() 调用的间隔时间过长, 将认为上一段平滑已经结束, 重新开启新一段平滑
local hideSpeed = 8.0    -- 4.0

local expectMaxTotateDegree = 1.0 -- 1.0

local offsetThreshold = 0.8 -- 0.5

-- ========================================================


local isActive = true -- 是否激活本功能



-- ========================================================

function JumpPositionSmooth:__init()
    self.controller = nil
    ----

    self.jumpHintType = JumpHintType.None
    self.isShow = false


    self.targetIsShow = false -- 目标值
    -- 0f:hide; 1f:show; 
    -- show 是瞬间触发的, 但 hide 则是个延时的, 需要延迟一段时间后才会真的 hide; 
    -- 以此来规避 偶发的散碎的 hide 指令 对 平滑过程的破坏;
    self.smoothIsShow = 0.0 -- 平滑值, 朝向 targetIsShow 运行

    self.lastTargetPos = Vector3()
    self.targetPos = Vector3()
    self.smoothPos = Vector3()

    self.lastTime = -1.0

    self.rotateRadian = Mathf.Deg2Rad * expectMaxTotateDegree
    
    self.isInit = false
end


function JumpPositionSmooth:__delete()
    self.co_1 = nil
end


function JumpPositionSmooth:Init(jumpHintType_, catCharacterMotor_, jumpDetectInterval_ )
    self.jumpHintType = jumpHintType_
    self.catCharacterMotor = catCharacterMotor_

    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()
    self.mCameraTF = self.mCamera.transform

    ------
    self.jumpDetectInterval = jumpDetectInterval_ 
    local frameNums = 1.0 / Time.deltaTime -- 通过此法来拙略地计算当前帧率
    self.rotateDegreeMultiplier = (frameNums > 45.0) and (1.0/2.8) or (1.0/1.3) -- 经验值...


    self.isInit = true
end


function JumpPositionSmooth:SetTargetPos( targetPos_ )

    if (targetPos_-self.targetPos).sqrMagnitude < 0.001 then 
        --print( "重复的 targetPos" )
        return
    end 

    self.lastTargetPos = self.targetPos
    self.targetPos = targetPos_
    if math.abs(Time.time - self.lastTime) > interval then
        -- 与上一次调用 Smooth() 的间隔太久了, 本帧重新开始;
        --print( "==== 重置 ===" )
        self.smoothPos = self.targetPos
    end

    self.lastTime = Time.time

end


function JumpPositionSmooth:SetShow(isShow_)
    self.targetIsShow = isShow_
end



-- 假的 update, 需要手动调用
function JumpPositionSmooth:Update()
    if isActive == false or self.isInit == false then
        return
    end

    --------
    local currentDegree = self:CalcDegree() -- 通常区间: [0.0, 15.0] 
    local degreeSpeed = currentDegree * self.rotateDegreeMultiplier
    self.rotateRadian = Mathf.Lerp( self.rotateRadian, Mathf.Deg2Rad * degreeSpeed, 0.6 )

    -- ==================== 显示 还是 隐藏 ====================
    -- 基于 targetIsShow, 运动 smoothIsShow, 最终影响 isShow 的值:
    if self.targetIsShow == false then
        -- to hide gradually
        if self.smoothIsShow > 0 then
            self.smoothIsShow = self.smoothIsShow - Time.deltaTime * hideSpeed
            if self.smoothIsShow < 0.01 then
                self.isShow = false
            end
        end
    else
        if self.isShow == false then
            -- to show immediately
            self.smoothIsShow = 1.0
            self.isShow = true
        end
    end

    -- ======================= 计算 ================================
    if self.isShow then
        self.smoothPos = self:CalcSmoothPos()
        JumpHint.ShowJumpHint(self.jumpHintType, self.smoothPos)
    else
        JumpHint.HideJumpHint(self.jumpHintType)
    end
end



-- =========================================== Self ================================================ --


function JumpPositionSmooth.SetActive( isActive_ )
    isActive = isActive_
end

function JumpPositionSmooth.GetActive()
    return isActive
end



function JumpPositionSmooth:CalcDegree()

    local centerPos = self.mCameraTF.position
    
    local toDst = self.targetPos - centerPos
    local toCurrent = self.smoothPos - centerPos

    local toDstFlat = Vector3.ProjectOnPlane( toDst,         Vector3.up )
    local toCurrentFlat = Vector3.ProjectOnPlane( toCurrent, Vector3.up )

    return Vector3.Angle( toCurrentFlat, toDstFlat )
end




function JumpPositionSmooth:CalcSmoothPos()

    local centerPos = self.mCameraTF.position
    
    local toSrc = self.lastTargetPos - centerPos
    local toDst = self.targetPos - centerPos
    local toCurrent = self.smoothPos - centerPos

    local toSrcFlat = Vector3.ProjectOnPlane( toSrc,         Vector3.up )
    local toDstFlat = Vector3.ProjectOnPlane( toDst,         Vector3.up )
    local toCurrentFlat = Vector3.ProjectOnPlane( toCurrent, Vector3.up )

    local newDir =  Vector3.RotateTowards( toCurrent, toDst, self.rotateRadian, 0 ).normalized

    local hDegree_src2current  = Vector3.Angle( toSrcFlat, toCurrentFlat )
    local hDegree_current2dst  = Vector3.Angle( toCurrentFlat, toDstFlat )

    local sum = hDegree_src2current + hDegree_current2dst

    if Mathf.Abs(sum) < 0.0001 then 
        return self.smoothPos
    end 

    local pct = hDegree_src2current / sum
    --print( "pct = " .. pct )
    local len = Mathf.Lerp( toSrc.magnitude, toDst.magnitude, pct );
    return centerPos + newDir * len
end




return JumpPositionSmooth